<script lang="ts">
 import {page} from '$app/state';
 import {goto,afterNavigate} from '$app/navigation';
 import {api,APIError} from '$lib/api';
 import {planPath,saveReviewAndRefresh,isOneDriveLink} from '$lib/ai-planner';
 type Review={decision:string;note:string;reviewerName:string;reviewedAt:string;version:number};
 type Source={id:string;jobName:string;title:string;description:string;relatedUrl?:string;status:string;priority:string;dueDate:string;version:number};
 type Recommendation={id:string;title:string;description:string;nextSteps?:string[];priority:string;recommendationType:string;suggestedDueDate:string;reason:string;sourceTaskIds:string[];sourceEvidence:Source[];review:Review;history:Review[]};
 type Plan={draft:{id:string;workspaceId:number;planDate:string;status:string;modelMode:string;modelProfile:string;generatedAt:string;selection:{actionable:number;selected:number;deferred:number}};recommendations:Recommendation[];stale:boolean;reviewed:number};
 type Summary={id:string;planDate:string;generatedAt:string;modelMode:string;stale:boolean};
 let workspaces=$state<{id:number;name:string;canManage:boolean}[]>([]),history=$state<Summary[]>([]),plan=$state<Plan|null>(null);
 let loading=$state(true),saving=$state(''),error=$state(''),notice=$state(''),forbidden=$state(false),date=$state(''),offset=$state(0),retryDraftId=$state('');
 let decisions=$state<Record<string,string>>({}),notes=$state<Record<string,string>>({});
 const wid=$derived(Number(page.params.id));
 const labels:Record<string,string>={PENDING:'Belum Ditinjau',SUITABLE:'Sesuai',NEEDS_REVISION:'Perlu Penyesuaian',REJECTED:'Tidak Direkomendasikan'};
 const kinds:Record<string,string>={CONTINUE_EXISTING:'Lanjutkan pekerjaan',REVIEW_EXISTING:'Tinjau pekerjaan',ADDRESS_OVERDUE:'Tindak lanjuti tenggat',QA_OR_REVISION:'Pemeriksaan atau revisi'};
 const priorities:Record<string,string>={LOW:'Rendah',MEDIUM:'Sedang',HIGH:'Tinggi',URGENT:'Mendesak'};
 const workspace=$derived(workspaces.find(w=>w.id===wid));
 function message(e:unknown){return e instanceof APIError&&e.status===403?'Anda tidak berwenang membuka perencana ini.':e instanceof Error?e.message:'Gagal memuat perencana.'}
 async function load(id?:string,selectedDate?:string):Promise<boolean>{loading=true;error='';notice='';try{const response=await api<{plan:Plan|null}>(planPath(wid,id,selectedDate));plan=response.plan;forbidden=false;retryDraftId='';decisions={};notes={};return true}catch(e){forbidden=e instanceof APIError&&e.status===403;error=message(e);plan=null;return false}finally{loading=false}}
 async function loadHistory(){try{history=(await api<{drafts:Summary[]}>(`/ai-plans/workspaces/${wid}/history?offset=${offset}`)).drafts}catch(e){error=message(e)}}
 afterNavigate(()=>{forbidden=false;date='';offset=0;history=[];plan=null;loading=true;void (async()=>{try{workspaces=(await api<{workspaces:typeof workspaces}>('/workspaces')).workspaces.filter(w=>w.canManage);if(!workspaces.some(w=>w.id===wid)){forbidden=true;error='Anda tidak berwenang membuka perencana ini.';loading=false;return}await Promise.all([load(),loadHistory()])}catch(e){error=message(e);loading=false}})()});
 async function save(r:Recommendation){if(!plan||plan.stale)return;const draftId=plan.draft.id;saving=r.id;error='';notice='';try{const result=await saveReviewAndRefresh(()=>api(`/ai-plans/workspaces/${wid}/${draftId}/recommendations/${r.id}/review`,{method:'PATCH',body:JSON.stringify({decision:decisions[r.id]??r.review.decision,note:notes[r.id]??r.review.note,version:r.review.version})}),()=>load(draftId));if(result==='saved')notice='Tinjauan tersimpan.';else{retryDraftId=draftId;error='Tinjauan tersimpan, tetapi gagal memuat data terbaru. Muat ulang sebelum meninjau lagi.'}}catch(e){error=e instanceof APIError&&e.status===409?'Tinjauan berubah atau rencana sudah usang. Muat ulang untuk melihat data terbaru.':message(e)}finally{saving=''}}
 function selectWorkspace(e:Event){const id=(e.currentTarget as HTMLSelectElement).value;void goto(`/workspace/${id}/ai-planner`)}
 function chooseDate(e:Event){date=(e.currentTarget as HTMLInputElement).value;void load(undefined,date||undefined)}
</script>
<svelte:head><title>AI Daily Job Planner | My-PLE</title></svelte:head>
<main class="planner">
 <a href={`/workspace/${wid}`}>← Kembali ke Workspace</a>
 <header><div><h1>AI Daily Job Planner</h1><p>Rekomendasi pekerjaan harian berdasarkan data Job Tracker.</p><p>Usulan kegiatan untuk evaluasi manusia. Bukan penugasan atau persetujuan akhir.</p></div></header>
 {#if workspaces.length}<div class="controls"><label>Workspace<select value={wid} onchange={selectWorkspace}>{#each workspaces as w}<option value={w.id}>{w.name}</option>{/each}</select></label><label>Tanggal rencana<input type="date" value={date||plan?.draft.planDate||''} onchange={chooseDate}/></label><button onclick={()=>{date='';void load()}}>Rencana terbaru</button></div>{/if}
 {#if loading}<p role="status">Memuat rencana…</p>{/if}
 {#if error}<div role="alert" class="alert"><p>{error}</p>{#if !forbidden}<button onclick={()=>void load(retryDraftId||plan?.draft.id,date||undefined)}>Muat ulang</button>{/if}</div>{/if}
 {#if notice}<p role="status" class="notice">{notice}</p>{/if}
 {#if !loading&&!forbidden}
  {#if plan}
   <section class="intro"><h2>{workspace?.name} · {plan.draft.planDate}</h2><p>Status: {plan.stale?'Usang': 'Menunggu tinjauan'} · {plan.draft.modelMode==='mock'?'Simulasi mock':'Dihasilkan AI'} · {new Date(plan.draft.generatedAt).toLocaleString('id-ID')}</p>{#if plan.stale}<p role="alert">Sumber pekerjaan berubah. Rencana ini hanya arsip; tinjauan baru dinonaktifkan.</p>{/if}</section>
   <div class="cards"><article><strong>{plan.draft.selection.actionable}</strong><span>Total pekerjaan aktif</span></article><article><strong>{plan.draft.selection.selected}</strong><span>Rekomendasi yang dipilih</span></article><article><strong>{plan.draft.selection.deferred}</strong><span>Pekerjaan yang ditunda</span></article><article><strong>{plan.reviewed}</strong><span>Rekomendasi dievaluasi</span></article></div>
   <section><h2>Rekomendasi</h2>{#each plan.recommendations as r (r.id)}<article class="recommendation"><div class="rec-head"><div><h3>{r.title}</h3><p>{r.sourceEvidence.map(s=>s.jobName||s.title).join(', ')}</p></div><span class="badge">{priorities[r.priority]??r.priority}</span></div><p>{kinds[r.recommendationType]??r.recommendationType} · {r.suggestedDueDate} · {labels[r.review.decision]??r.review.decision}</p><p>{r.description}</p>{#if r.nextSteps?.length}<h4>Langkah berikutnya</h4><ol>{#each r.nextSteps as step}<li>{step}</li>{/each}</ol>{/if}<p>{r.reason}</p><details><summary>Detail dan bukti sumber</summary>{#each r.sourceEvidence as source}<div class="source"><p><strong>{source.title}</strong> · {source.status} · versi {source.version}</p><p>{source.description}</p><p>Tenggat: {source.dueDate||'Tidak ada'}</p>{#if isOneDriveLink(source.relatedUrl)}<a href={source.relatedUrl} target="_blank" rel="noopener noreferrer">Buka dokumen sumber</a><br/>{/if}<a href={`/workspace/${wid}?task=${encodeURIComponent(source.id)}`}>Buka pekerjaan asli di Job Tracker</a></div>{/each}</details><div class="review"><label>Keputusan tinjauan<select value={decisions[r.id]??r.review.decision} onchange={e=>decisions[r.id]=(e.currentTarget as HTMLSelectElement).value} disabled={plan.stale||saving===r.id}>{#each Object.entries(labels) as [value,label]}<option {value}>{label}</option>{/each}</select></label><label>Catatan tinjauan<textarea rows="3" maxlength="2000" value={notes[r.id]??r.review.note} oninput={e=>notes[r.id]=(e.currentTarget as HTMLTextAreaElement).value} disabled={plan.stale||saving===r.id}></textarea></label><button onclick={()=>void save(r)} disabled={plan.stale||saving===r.id}>{saving===r.id?'Menyimpan…':'Simpan tinjauan'}</button></div>{#if r.review.version>0}<p class="reviewer">Ditinjau {r.review.reviewerName} · {new Date(r.review.reviewedAt).toLocaleString('id-ID')}</p>{/if}<details><summary>Riwayat tinjauan ({r.history.length})</summary><ol>{#each r.history as event}<li>{labels[event.decision]} · {event.reviewerName} · {new Date(event.reviewedAt).toLocaleString('id-ID')}{#if event.note}<p>{event.note}</p>{/if}</li>{:else}<li>Belum ada riwayat.</li>{/each}</ol></details></article>{:else}<p>Belum ada rekomendasi untuk rencana ini.</p>{/each}</section>
  {:else if !error}<p>Belum ada rencana yang diterbitkan untuk tanggal ini.</p>{/if}
  <section><h2>Riwayat rencana</h2><ul>{#each history as item}<li><button onclick={()=>{date=item.planDate;void load(item.id)}}>{item.planDate} · {item.modelMode==='mock'?'Simulasi mock':'Dihasilkan AI'} · {new Date(item.generatedAt).toLocaleString('id-ID')}{item.stale?' · Usang':''}</button></li>{:else}<li>Belum ada riwayat rencana.</li>{/each}</ul><button disabled={offset===0} onclick={()=>{offset=Math.max(0,offset-20);void loadHistory()}}>Sebelumnya</button><button disabled={history.length<20} onclick={()=>{offset+=20;void loadHistory()}}>Berikutnya</button></section>
 {/if}
</main>
<style>
 .planner{max-width:1100px;margin:auto;padding:1.5rem;color:var(--text-primary,#17243a)}.planner *{box-sizing:border-box}.planner header,.intro,.recommendation,.planner section{min-width:0}.planner h1{margin:.7rem 0}.controls,.cards,.rec-head{display:flex;gap:1rem;flex-wrap:wrap}.controls{align-items:end;margin:1.5rem 0}.controls label,.review label{display:grid;gap:.35rem}.controls select,.controls input,.review select,.review textarea{font:inherit;padding:.6rem;border:1px solid #9aa9bc;border-radius:.5rem;background:white;max-width:100%;width:100%}.cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));margin:1.5rem 0}.cards article,.recommendation,.intro{border:1px solid #d7e0eb;border-radius:.8rem;padding:1rem;background:white}.cards article{display:grid;gap:.4rem}.cards strong{font-size:1.8rem}.rec-head{justify-content:space-between}.rec-head h3{margin:0}.badge{background:#e7efff;color:#183e87;border-radius:1rem;padding:.3rem .7rem;height:max-content}.recommendation{margin:1rem 0;overflow-wrap:anywhere}.source{border-left:3px solid #7794c7;padding-left:1rem}.review{display:grid;gap:.8rem;margin:1rem 0}.reviewer{font-size:.9rem;color:#53637b}.planner button{font:inherit;cursor:pointer;padding:.55rem .8rem;border:1px solid #8da4c6;border-radius:.5rem;background:#f5f8ff}.planner button:disabled{cursor:not-allowed;opacity:.6}.planner a{color:#174eab}.alert{color:#9d1c20}.notice{color:#17603b}.planner li{margin:.5rem 0}@media(max-width:700px){.planner{padding:1rem}.cards{grid-template-columns:repeat(2,minmax(0,1fr))}.controls>*{width:100%}}@media(max-width:380px){.cards{grid-template-columns:1fr}}
</style>
